    public static class TomášGarrigueMasaryk
    {
        private const string Source = "https://cs.wikiquote.org/wiki/Tom%C3%A1%C5%A1_Garrigue_Masaryk";

        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = Source, Text = "Fašismus je anonymní společnost nespokojených a odmítnutých s omezeným ručením k výrobě politických báchorek a lupičských historek.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Honbou po štěstí nikdo se šťastným nestal.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Jen ať jsou spory, ale ať se bojuje s rozumem a poctivě.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Je stejně potřebné přemýšlet o tom, jak užívat svůj volný čas, nejen o tom, jak dobývat bohatství.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Kniha je nejlepším přítelem. Jsme knihami spojeni s duchem všech národů a dob.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Národ, který chce bojovat, nemůže být ztracen.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Nestačí, když hodiny špatně jdou, postrčit ručičky a dál se nestarat…", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Nerozčilujme se otázkami hospodářskými a politickými – problém dneška není jen hospodářský a politický, nýbrž především mravní.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Nikdy jsem se nepokládal za víc než za dělníka v tom velkém světě.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Špatné překonávat dobrým – to není tak těžké, ale těžko je překonávat dobré lepším.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Šťastný je ten, kdo má bohatý obsah životní, šťastný je ten, kdo dovede poctivým úsilím zčásti uskutečnit své ideály.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "V metafysice lidé hledají bůhvíjaké hluboké a tajuplné vědomosti, a zatím právě metafysika, aspoň jak byla pěstována posud, je na obsah chudá, chudičká; je to jen malý konkurenční podnik, který si zařídila filosofie proti theologii.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "V tom chybují filosofové i theologové: theologie není náboženstvím, jen theorií náboženství; filosofie může nahradit theologii, ale nedovede nahradit náboženství.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Vůdcem dobrým bude ten, kdo dovede sloužit a kdo cítí, že sám je veden a veden být chce.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Bez osobní odvahy a odpovědnosti nelze dělat politiku opravdovou demokratickou a lidovou.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Demokracie není panováním, nýbrž prací k zabezpečení spravedlnosti. A spravedlnost je matematika humanity.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Demokracii dělají demokrati a lepší demokracii lepší demokrati. Pravda je ve všem, i v politice, nejpraktičtější.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Existence duší je pravým základem demokracie: věčné věčnému nemůže být lhostejné, nesmrtný je nesmrtnému roven.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Má-li naše demokracie své nedostatky, musíme překonávat ty nedostatky, ale ne překonávat demokracii.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Komunism je možný, ale jen mezi bratry, v rodině nebo v náboženské a v přátelské obci; může být udržen jen opravdovou láskou. Nepřijímám třídního boje.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Jsou lidé, kteří nechtějí sebe znát; sebepoznání prý je těžké.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Nepotřebujeme mravnosti a náboženství abstraktně, v soustavách a v knihách, ale v životě, v hospodaření a v politice. Etika není pro psací stůl, náboženství není pro kostel.", Author = "Tomáš Garrigue Masaryk" },
            new Quote { Id = Source, Text = "Zbožnost korunuje a posvěcuje lásku. Náboženství bez lidskosti nemůže být správné; lidskost bez zbožnosti nemůže být úplná.", Author = "Tomáš Garrigue Masaryk" },
        };
    }
